  for w in list {
    let owner = w["kCGWindowOwnerName"] as? String ?? ""
    if owner.lowercased().contains("hello") || owner.lowercased().contains("tauri") {
      print(owner, w["kCGWindowNumber"] ?? "", w["kCGWindowBounds"] ?? "")
